using K=MachineKind;using E=EnergyMedium;
static int checks=0;
static void require(bool ok,const char* why){checks++;if(!ok)throw std::runtime_error(why);}
static bool near(double a,double b){return std::abs(a-b)<1e-6;}
static Factory empty(){Factory f;f.machines.clear();f.energyLinks.clear();f.blueprints.clear();f.reagentworks={};f.chemicals=0;f.farmProduce=0;f.farmInventory.clear();for(auto& [key,n]:f.stock)n=0;f.water=20;f.waterworks={};f.electricity=100000;f.tick=0;return f;}
static Machine& add(Factory& f,Position p,K k,int d=0){require(f.build(p,k,d),"build test apparatus");return *f.at(p);}
static Batch feed(Factory& f,const std::string& key,double grams){Batch b;b.id=f.nextId++;addIngredient(b.food,key,grams,f.nextComponent++,f.nextOperation++);b.matter=projectCell(b.food);return b;}
static void run(Factory& f,int n,bool on=true){for(int i=0;i<n;i++){f.tick++;runReagentWorks(f,[on](Position,double){return on;});}}
static double mass(const Batch& b){return analyse(b.food).mass;}
static double held(const Machine& m){return (m.item?mass(*m.item):0)+(m.sideOutput?mass(*m.sideOutput):0);}
static Batch reacted(K k,const std::string& key,const std::string& source,double temp=65){auto f=empty();auto& m=add(f,{0,0},k);m.ingredient=key;m.temperature=temp;m.reagentProcess.starter=1;m.item=feed(f,source,100);if(k==K::SaltReactor)m.item->reagent.mineral=true;run(f,m.duration);require(m.ready&&m.item.has_value(),"reaction produces a real lot");return *m.item;}
static Batch pureLot(Factory& f,const std::string& key,double grams){auto b=feed(f,key,grams);b.reagent={key,grams,0,false,false};return b;}
