 {auto f=empty();auto& m=add(f,{0,0},K::ReagentEvaporator);m.temperature=150;m.item=reacted(K::ReagentExtractor,"pectin","berry");double initial=mass(*m.item),active=m.item->reagent.active;run(f,m.duration);require(near(held(m),initial)&&m.item->reagent.active<active&&m.sideOutput->reagent.active==0,"overheating converts active material to impurity without duplicating it into condensate");}
