 {auto f=empty();auto& m=add(f,{0,0},K::ReagentIntake);m.item=reacted(K::ReagentExtractor,"pectin","berry");m.item->reagent.assayed=true;run(f,3);require(m.item&&f.chemicals==0,"assay does not bypass purity and concentration limits");require(f.configure({0,0},"reagent-reject")&&m.sideOutput&&!m.item,"off-spec lots can be routed from the side port for reprocessing");}
