 require(f.reagentworks.inventory["pectin"]>0&&f.reagentworks.inventory["culture"]>0&&f.reagentworks.inventory["nutrient"]>0,"three powered physical lines feed crop extraction, cultures and farm minerals into real factory stock");require(genericChemicals(f)<1e-6,"physical lab output remains named");require(f.water<20&&f.reagentworks.returnedWater>0,"integrated process consumes real water and recovers actual returns");require(f.electricity<100000,"physical AC input is actually consumed");
